def balanced(s):
    """Return True if all brackets in s are balanced outside double-quoted strings."""
    stack = []
    matching = {')': '(', ']': '[', '}': '{'}
    in_string = False
    i = 0
    n = len(s)

    while i < n:
        ch = s[i]

        if in_string:
            if ch == '\\':
                i += 2
                continue
            if ch == '"':
                in_string = False
            i += 1
            continue

        if ch == '"':
            in_string = True
        elif ch in '([{':
            stack.append(ch)
        elif ch in ')]}':
            if not stack or stack[-1] != matching[ch]:
                return False
            stack.pop()

        i += 1

    return not in_string and not stack
